import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());String s = br.readLine();int count = 0;for (int i = 1; i < n; i++) {if (s.charAt(i) == s.charAt(i - 1)) {count++;}}System.out.println(count);}}